const raw=String($input.first()?.json?.output||'').trim();
const candidate=$('Prepare Research Input').first().json.candidate;
function parse(s){let t=s.trim();const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a>=0&&b>a)t=t.slice(a,b+1);t=t.replace(/,\s*([}\]])/g,'$1');return JSON.parse(t)}
let x;try{x=parse(raw)}catch(e){return [{json:{topic:candidate.topic,candidate,research_valid:false,research_failure_reason:'Primary Tavily research returned invalid JSON: '+e.message}}]}
const src=Array.isArray(x.source_register)?x.source_register:[];
const good=src.filter(s=>/^https?:\/\/[^\s]+$/i.test(String(s.url||''))&&String(s.title||'').trim()&&String(s.evidence||'').trim().length>=40);
const unique=[...new Map(good.map(s=>[s.url,s])).values()];
const official=unique.filter(s=>/official|primary|documentation|pricing|product page|github repository/i.test(String(s.source_type||'')+' '+String(s.title||'')));
const valid=String(x.research_status||'').toUpperCase()==='COMPLETE'&&unique.length>=3&&official.length>=2&&x.claim_evidence_map&&Array.isArray(x.key_questions)&&Array.isArray(x.suggested_structure);
return [{json:{...x,topic:x.topic||candidate.topic,candidate,source_register:unique,source_count:unique.length,official_source_count:official.length,research_valid:Boolean(valid),research_failure_reason:valid?null:(x.research_failure_reason||'Primary research did not meet source-quality requirements.')}}];
